const express = require('express');
const app = express();

// Multi-tenant Solidity contract search indexing service
// Indexes contract ABIs, events, and function signatures

class TenantRegistry {
  constructor() {
    this._tenants = Object.create(null);
    this._indexConfig = Object.create(null);
  }

  registerTenant(tenantId, config) {
    if (!tenantId || typeof tenantId !== 'string') throw new Error('Invalid tenant ID');
    if (!/^[a-zA-Z0-9_-]+$/.test(tenantId)) throw new Error('Invalid tenant ID format');
    this._tenants[tenantId] = { created: Date.now(), ...config };
    this._indexConfig[tenantId] = { maxDocs: 10000, fields: ['name', 'signature', 'selector'] };
  }

  getTenant(tenantId) {
    return this._tenants[tenantId] || null;
  }
}

class SearchIndex {
  constructor() {
    this._documents = Object.create(null);
    this._metadata = Object.create(null);
  }

  ensureTenantIndex(tenantId) {
    if (!this._documents[tenantId]) {
      this._documents[tenantId] = [];
      this._metadata[tenantId] = { count: 0, lastUpdated: null };
    }
  }

  addDocument(tenantId, doc) {
    this.ensureTenantIndex(tenantId);
    this._documents[tenantId].push(doc);
    this._metadata[tenantId].count++;
    this._metadata[tenantId].lastUpdated = Date.now();
  }

  search(tenantId, query) {
    this.ensureTenantIndex(tenantId);
    const docs = this._documents[tenantId];
    return docs.filter(d => {
      return Object.keys(query).every(k => d[k] && d[k].includes(query[k]));
    });
  }
}

class FieldMappingEngine {
  constructor() {
    this._mappings = Object.create(null);
  }

  // Recursively merge field mapping configurations
  // Supports nested Solidity type mappings (struct fields, tuple components)
  deepMergeMapping(target, source, depth = 0) {
    if (depth > 10) return target;
    const BLOCKED_KEYS = new Set(['__proto__', 'constructor', 'prototype']);
    for (const key of Object.keys(source)) {
      if (BLOCKED_KEYS.has(key)) continue;
      if (typeof source[key] === 'object' && source[key] !== null && !Array.isArray(source[key])) {
        if (typeof target[key] !== 'object' || target[key] === null) {
          target[key] = Object.create(null);
        }
        this.deepMergeMapping(target[key], source[key], depth + 1);
      } else {
        target[key] = source[key];
      }
    }
    return target;
  }

  setMapping(tenantId, mappingConfig) {
    if (!this._mappings[tenantId]) {
      this._mappings[tenantId] = Object.create(null);
      this._mappings[tenantId].fields = Object.create(null);
      this._mappings[tenantId].analyzers = Object.create(null);
    }
    // Merge new mapping config into existing tenant mapping
    this.deepMergeMapping(this._mappings[tenantId], mappingConfig);
  }

  getMapping(tenantId) {
    return this._mappings[tenantId] || null;
  }
}

const registry = new TenantRegistry();
const searchIndex = new SearchIndex();
const fieldEngine = new FieldMappingEngine();

app.use(express.json());

// Middleware: tenant isolation check
app.use('/api/:tenantId/*', (req, res, next) => {
  const { tenantId } = req.params;
  if (!registry.getTenant(tenantId)) {
    return res.status(404).json({ error: 'Tenant not found' });
  }
  next();
});

app.post('/api/tenants', (req, res) => {
  try {
    const { tenantId, config } = req.body;
    registry.registerTenant(tenantId, config || {});
    res.json({ success: true, tenantId });
  } catch (e) {
    res.status(400).json({ error: e.message });
  }
});

app.post('/api/:tenantId/index', (req, res) => {
  const { tenantId } = req.params;
  const { document } = req.body;
  if (!document || typeof document !== 'object') {
    return res.status(400).json({ error: 'Invalid document' });
  }
  searchIndex.addDocument(tenantId, document);
  res.json({ success: true });
});

app.post('/api/:tenantId/mappings', (req, res) => {
  const { tenantId } = req.params;
  const { mappingConfig } = req.body;
  if (!mappingConfig || typeof mappingConfig !== 'object') {
    return res.status(400).json({ error: 'Invalid mapping config' });
  }
  fieldEngine.setMapping(tenantId, mappingConfig);
  res.json({ success: true, mapping: fieldEngine.getMapping(tenantId) });
});

app.get('/api/:tenantId/search', (req, res) => {
  const { tenantId } = req.params;
  const query = req.query;
  const results = searchIndex.search(tenantId, query);
  res.json({ results });
});

// Admin endpoint to check service health
app.get('/health', (req, res) => {
  const status = { healthy: true, uptime: process.uptime() };
  // Check if any pollution has occurred (canary)
  const testObj = {};
  if (testObj.polluted) {
    status.integrity = 'compromised';
  }
  res.json(status);
});

module.exports = app;
